export function script(input) {
  const packageSpec = String(input.packageSpec == null ? '' : input.packageSpec).trim();
  if (!packageSpec) {
    throw new Error('Enter one npm package name with an optional version.');
  }
  const separatorIndex = packageSpec.lastIndexOf('@');
  const packageName = separatorIndex > 0 ? packageSpec.slice(0, separatorIndex) : packageSpec;
  const requestedVersion = separatorIndex > 0 ? packageSpec.slice(separatorIndex + 1) : '';
  return {
    packageSpec: packageSpec,
    packageSpecs: [packageSpec],
    packageName: packageName,
    requestedVersion: requestedVersion,
    researchFocus: String(input.researchFocus == null ? '' : input.researchFocus).trim(),
    authorizationNotes: String(input.authorizationNotes == null ? '' : input.authorizationNotes).trim()
  };
}

export function script(input) {
  return {
    osvEvidence: {
      findings: Array.isArray(input.findings) ? input.findings : [],
      summary: input.summary && typeof input.summary === 'object' ? input.summary : {}
    }
  };
}

export function script(input) {
  const failure = input.failure;
  const reason = failure && typeof failure === 'object' && failure.reason != null ? failure.reason : failure;
  const rawMessage = reason && typeof reason === 'object' ? reason.message : reason;
  const message = String(rawMessage || 'Unknown OSV query failure.').trim().slice(0, 1000);
  return {
    osvEvidence: {
      findings: [],
      summary: {
        status: 'failed',
        findingCount: 0,
        warningCount: 1,
        warning: 'OSV query failed: ' + message
      }
    }
  };
}

export function script(input) {
  const successEvidence = input.successEvidence && typeof input.successEvidence === 'object' ? input.successEvidence : null;
  const failureEvidence = input.failureEvidence && typeof input.failureEvidence === 'object' ? input.failureEvidence : null;
  const evidence = successEvidence || failureEvidence;
  if (evidence) {
    return {
      osvFindings: Array.isArray(evidence.findings) ? evidence.findings : [],
      osvSummary: evidence.summary && typeof evidence.summary === 'object' ? evidence.summary : {}
    };
  }
  return {
    osvFindings: [],
    osvSummary: {
      status: 'unavailable',
      findingCount: 0,
      warningCount: 1,
      warning: 'No OSV evidence branch completed.'
    }
  };
}

export function script(input) {
  const sourceBundle = String(input.sourceBundle == null ? '' : input.sourceBundle);
  const semgrepFindings = Array.isArray(input.semgrepFindings) ? input.semgrepFindings : [];
  const sourceStatus = input.sourceStatus && typeof input.sourceStatus === 'object' ? input.sourceStatus : {};
  const packageProvenance = input.packageProvenance && typeof input.packageProvenance === 'object' ? input.packageProvenance : null;
  return {
    sourceEvidence: {
      sourceBundle: sourceBundle,
      sourceStatus: Object.assign({}, sourceStatus, { semgrepStatus: 'completed' }),
      packageProvenance: packageProvenance,
      semgrepFindings: semgrepFindings,
      semgrepCount: Number(input.semgrepCount || semgrepFindings.length),
      scannerFailure: null,
      scannerCaveat: null
    }
  };
}

