export function script(input) {
  const successEvidence = input.successEvidence && typeof input.successEvidence === 'object' ? input.successEvidence : null;
  const failureEvidence = input.failureEvidence && typeof input.failureEvidence === 'object' ? input.failureEvidence : null;
  const sourceEvidence = successEvidence || failureEvidence;
  if (sourceEvidence) {
    return { sourceEvidence: sourceEvidence };
  }
  return {
    sourceEvidence: {
      sourceBundle: '',
      sourceStatus: { sourceProvided: false, semgrepStatus: 'unavailable' },
      packageProvenance: null,
      semgrepFindings: [],
      semgrepCount: 0,
      scannerFailure: { stage: 'semgrep_scan', message: 'No source evidence branch completed.' },
      scannerCaveat: 'No source evidence branch completed.'
    }
  };
}

export function script(input) {
  const toJson = function (value, maxChars) {
    let serialized;
    try {
      serialized = JSON.stringify(value);
    } catch (error) {
      serialized = JSON.stringify({ warning: 'Value could not be serialized.' });
    }
    return String(serialized == null ? 'null' : serialized).slice(0, maxChars);
  };
  const registryRecords = (Array.isArray(input.registryRecords) ? input.registryRecords : []).slice(0, 5).map(function (record) {
    if (!record || typeof record !== 'object' || Array.isArray(record)) return record;
    const boundedRecord = Object.assign({}, record);
    delete boundedRecord.rawMetadata;
    return boundedRecord;
  });
  const registryWarnings = (Array.isArray(input.registryWarnings) ? input.registryWarnings : []).slice(0, 20);
  const osvFindings = (Array.isArray(input.osvFindings) ? input.osvFindings : []).slice(0, 30);
  const sourceEvidence = input.sourceEvidence && typeof input.sourceEvidence === 'object' ? input.sourceEvidence : {};
  const semgrepLeads = (Array.isArray(sourceEvidence.semgrepFindings) ? sourceEvidence.semgrepFindings : []).slice(0, 100);
  const sourceBundle = String(sourceEvidence.sourceBundle == null ? '' : sourceEvidence.sourceBundle).slice(0, 1500000);
  const packageContext = {
    packageSpec: String(input.packageSpec == null ? '' : input.packageSpec),
    packageName: String(input.packageName == null ? '' : input.packageName),
    requestedVersion: String(input.requestedVersion == null ? '' : input.requestedVersion),
    researchFocus: String(input.researchFocus == null ? '' : input.researchFocus),
    authorizationNotes: String(input.authorizationNotes == null ? '' : input.authorizationNotes)
  };
  const lines = [
    'Investigate this installable published npm package and produce the required evidence-backed Markdown report.',
    'Package context: ' + toJson(packageContext, 20000),
    'npm registry records: ' + toJson(registryRecords, 100000),
    'npm registry warnings: ' + toJson(registryWarnings, 20000),
    'OSV findings: ' + toJson(osvFindings, 250000),
    'OSV summary: ' + toJson(input.osvSummary && typeof input.osvSummary === 'object' ? input.osvSummary : {}, 50000),
    'Published-package provenance: ' + toJson(sourceEvidence.packageProvenance || null, 50000),
    'Published-package source status: ' + toJson(sourceEvidence.sourceStatus || {}, 50000),
    'Semgrep leads (maximum 100): ' + toJson(semgrepLeads, 500000),
    'Semgrep failure/caveat: ' + toJson({ scannerFailure: sourceEvidence.scannerFailure || null, scannerCaveat: sourceEvidence.scannerCaveat || null }, 10000),
    'Published source bundle (maximum 1,500,000 source characters): ' + toJson(sourceBundle, 1600000),
    'Scanner outputs are leads only. Empty or failed scanner output does not prove absence of vulnerabilities.'
  ];
  return { agentInput: lines.join('\n\n') };
}

export function script(input) {
  const reportText = String(input.agentResponse == null ? '' : input.agentResponse).trim();
  const fence = reportText.match(/```sentris-findings\s*([\s\S]*?)```/i);
  let findings = [];
  if (fence) {
    try {
      const parsed = JSON.parse(fence[1]);
      findings = parsed && Array.isArray(parsed.findings) ? parsed.findings : [];
    } catch (error) {
      findings = [];
    }
  }
  const packageSpec = String(input.packageSpec == null ? '' : input.packageSpec).trim();
  const packageName = String(input.packageName == null ? '' : input.packageName).trim();
  const provenance = input.packageProvenance && typeof input.packageProvenance === 'object' ? input.packageProvenance : {};
  const resolvedVersion = typeof provenance.resolvedVersion === 'string' ? provenance.resolvedVersion.trim() : '';
  const allowedSeverities = ['critical', 'high', 'medium', 'low', 'info', 'unknown'];
  const isConcreteEvidence = function (value) {
    if (typeof value !== 'string') return false;
    const evidence = value.trim();
    const sourceMatch = evidence.match(/^source:([^:\r\n]+):L([1-9]\d*)(?:-L?([1-9]\d*))?$/i);
    if (sourceMatch) {
      const startLine = Number(sourceMatch[2]);
      const endLine = sourceMatch[3] ? Number(sourceMatch[3]) : startLine;
      return sourceMatch[1].trim().length > 0 && endLine >= startLine;
    }
    if (/^scanner:[^:\s]+:\S(?:[\s\S]*\S)?$/i.test(evidence)) return true;
    return /^tool:[^:\s]+:\S(?:[\s\S]*\S)?$/i.test(evidence);
  };
  const normalizeEvidence = function (value) {
    const candidates = Array.isArray(value) ? value : typeof value === 'string' ? [value] : [];
    return candidates.filter(isConcreteEvidence).map(function (item) { return item.trim(); });
  };
  const analyticsResults = findings.filter(function (finding) {
    if (!finding || typeof finding !== 'object' || Array.isArray(finding)) return false;
    const title = typeof finding.title === 'string' ? finding.title.trim() : '';
    const evidence = normalizeEvidence(finding.evidence);
    return title.length > 0 && evidence.length > 0;
  }).map(function (finding) {
    const title = finding.title.trim();
    const evidence = normalizeEvidence(finding.evidence);
    const requestedSeverity = typeof finding.severity === 'string' ? finding.severity.trim().toLowerCase() : 'unknown';
    const severity = allowedSeverities.indexOf(requestedSeverity) >= 0 ? requestedSeverity : 'unknown';
    const affectedPackage = typeof finding.affectedPackage === 'string' ? finding.affectedPackage.trim() : '';
    const affectedVersion = typeof finding.affectedVersion === 'string' ? finding.affectedVersion.trim() : '';
    const vulnerabilityClass = typeof finding.vulnerabilityClass === 'string' ? finding.vulnerabilityClass.trim() : '';
    const confidence = typeof finding.confidence === 'string' && finding.confidence.trim() ? finding.confidence.trim() : 'medium';
    const nullableString = function (value) { return typeof value === 'string' && value.trim() ? value.trim() : null; };
    return {
      scanner: 'gemini-autonomous-npm',
      severity: severity,
      finding_hash: [packageSpec, affectedVersion || resolvedVersion || '', vulnerabilityClass || '', title, evidence[0]].join(':'),
      asset_key: packageSpec,
      package: affectedPackage || packageName,
      version: affectedVersion || resolvedVersion || null,
      title: title,
      confidence: confidence,
      vulnerability_class: vulnerabilityClass || null,
      evidence: evidence,
      impact: nullableString(finding.impact),
      verification: nullableString(finding.verification),
      remediation: nullableString(finding.remediation)
    };
  });
  return { reportText: reportText, analyticsResults: analyticsResults };
}
